import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Invoice, Product } from '../models/invoice';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
export enum InvoiceStatus {
  Requested = 0,
 Pending = 1,
 Completed = 2
}

@Injectable({
  providedIn: 'root'
})
export class InvoiceService {
  private baseUrl = `${environment.apiUrl}/invoice`;

  constructor(private http: HttpClient) {}

  createInvoice(dto: Invoice): Observable<Invoice> {
    return this.http.post<Invoice>(`${this.baseUrl}/create`, dto);
  }

  updateInvoice(id: number, dto: Invoice): Observable<Invoice> {
    return this.http.put<Invoice>(`${this.baseUrl}/update/${id}`, dto);
  }


  getAllInvoices(): Observable<Invoice[]> {
    return this.http.get<Invoice[]>(`${this.baseUrl}/GetAll`);
  }

  getInvoiceById(id: number): Observable<Invoice> {
    return this.http.get<Invoice>(`${this.baseUrl}/GetById/${id}`);
  }
getRequestedInvoices(): Observable<Invoice[]> {
return this.http.get<Invoice[]>(`${this.baseUrl}/requested`);
}

getPendingInvoices(): Observable<Invoice[]> {
  return this.http.get<Invoice[]>(`${this.baseUrl}/pending`);
}

getCompletedInvoices(): Observable<Invoice[]> {
  return this.http.get<Invoice[]>(`${this.baseUrl}/completed`);
}
updateStatus(id: number, status: number): Observable<InvoiceStatus> {
  return this.http.put<InvoiceStatus>(`${this.baseUrl}/update-status/${id}`, {status})
}

}